import java.util.Arrays;
public class QaArrayCopy {
 public static void main(String[] args) {
  int[] expected = {200, 201};
  int[] actual = Arrays.copyOf(expected, expected.length);
  actual[1] = 500;
  if (Arrays.equals(expected, actual)) throw new AssertionError("Must differ");
  System.out.println("Mismatch detected");
 }
}

