lessons.code:
public class AccountDemo {
 static class Account {
  private int balance;
  Account(int balance) {
   if (balance < 0) throw new IllegalArgumentException("balance");
   this.balance = balance;
  }
  void deposit(int amount) {
   if (amount <= 0) throw new IllegalArgumentException("amount");
   balance += amount;
  }
  int balance() { return balance; }
 }
 public static void main(String[] args) {
  Account account = new Account(100);
  account.deposit(25);
  System.out.println(account.balance());
 }
}

lessons.qacode:
public class QaAccount {
 public static void main(String[] args) {
  AccountDemo.Account account = new AccountDemo.Account(100);
  try {
   account.deposit(-10);
   throw new AssertionError("Negative deposit accepted");
  } catch (IllegalArgumentException expected) {
   if (account.balance() != 100) throw new AssertionError("State changed");
  }
 }
}

